        data: await dataURL(await canvasBlob(canvas, "image/png")),
        width: canvas.width,
        height: canvas.height,
        warning:
          "Farbkonvertierung durch den Browser. Aufnahmedatum aus dem Dateinamen.",
        captureDate: "",
        captureDay: "",
