      return null;
    const people = im.people.filter(
      (r) =>
        [r.x, r.y, r.w, r.h, r.score].every(Number.isFinite) &&
        r.w > 0 &&
        r.h > 0,
    );
    if (!people.length) return null;
    const prominent = (items) =>
      items.reduce((a, r) =>
        r.w * r.h * r.score > a.w * a.h * a.score ? r : a,
      );
