    Object.assign(result.style, {
      autoKerning: false,
      kerning: 0,
      ligatures: false,
      strokeFlag: true,
      fillFlag: true,
      fillFirst: true,
      outlineWidth: MKWFamily.outlineWidth,
      strokeColor: rgb(MKWFamily.outline),
    });
