async function withPSDProfile(buffer) {
  // Add Photoshop image resource 1039 (ICC), using the same sRGB profile as JPG.
  const profile = new Uint8Array(
      await (await fetch("static/srgb.icc")).arrayBuffer(),
    ),
    data = new Uint8Array(buffer),
    view = new DataView(buffer),
    offset = 30 + view.getUint32(26),
    length = view.getUint32(offset),
    resource = new Uint8Array(12 + profile.length + (profile.length % 2)),
    rv = new DataView(resource.buffer);
  resource.set([56, 66, 73, 77]);
  rv.setUint16(4, 1039);
  rv.setUint32(8, profile.length);
  resource.set(profile, 12);
  const size = new Uint8Array(4);
  new DataView(size.buffer).setUint32(0, length + resource.length);
  return new Blob(
    [
      data.subarray(0, offset),
      size,
      data.subarray(offset + 4, offset + 4 + length),
      resource,
      data.subarray(offset + 4 + length),
    ],
    { type: "image/vnd.adobe.photoshop" },
  );
}
