      ddx = 6 * (u * (q.x - 2 * p.x + a.x) + t * (b.x - 2 * q.x + p.x)),
      ddy = 6 * (u * (q.y - 2 * p.y + a.y) + t * (b.y - 2 * q.y + p.y)),
